def split_words(txt):
    # Split by whitespace first
    if txt:
        words = txt.split()
    else:
        words = []

    # If no words found, return empty list
    if not words:
        return []

    # Check for commas
    if ',' in words:
        # Split on commas
        return words.split(',')

    # Split on whitespace
    return words.split()
