```python
def bf(planet1, planet2):
    # Define the planets in order from closest to farthest
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    # Check if both are valid planet names
    if planet1 not in planets or planet2 not in planets:
        return ()

    # Find planets between planet1 and planet2 (inclusive)
    # Sort by proximity to sun (ascending)
    result = sorted([planet for planet in planets if planet1 <= planet <= planet2])
    return tuple(result)
